package com.ebuddy.service;
import com.ebuddy.domain.*; import com.ebuddy.repo.*; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.util.*;
@Component public class OutboxPublisher { private final OutboxRepository outbox; private final MessageRepository messages; private final SimpMessagingTemplate stomp; public OutboxPublisher(OutboxRepository o,MessageRepository m,SimpMessagingTemplate s){outbox=o;messages=m;stomp=s;} @Scheduled(fixedDelay=500) public void publish(){for(var item:outbox.findAll().stream().filter(x->x.getState()==OutboxState.pending).limit(100).toList()){try{var m=messages.findById(item.getMessageId());if(m.isPresent()){var x=m.get();var data=new LinkedHashMap<String,Object>();data.put("id",x.getId().toString());data.put("from_user_id",x.getSenderUserId().toString());data.put("to_user_id",x.getRecipientUserId().toString());data.put("client_message_id",x.getClientMessageId());data.put("sequence",x.getSequence());data.put("body",x.getBody());data.put("status",x.getStatus().name());data.put("created_at",x.getCreatedAt().toString());data.put("delivered_at",x.getDeliveredAt()==null?null:x.getDeliveredAt().toString());data.put("read_at",x.getReadAt()==null?null:x.getReadAt().toString());var event=Map.of("v",1,"type",item.getEventType(),"event_id",x.getId().toString(),"cursor",String.valueOf(Optional.ofNullable(x.getSequence()).orElse(0L)),"data",data);var target=item.getEventType().startsWith("message.status")?x.getSenderUserId():x.getRecipientUserId();stomp.convertAndSendToUser(target.toString(),"queue/events",event);}item.done();outbox.save(item);}catch(RuntimeException e){item.retry();outbox.save(item);}}}}
